--
-- Table structure for table `alat`
--

CREATE TABLE `alat` (
  `id` int(11) NOT NULL,
  `kategori_id` int(11) DEFAULT NULL,
  `nama_alat` varchar(150) NOT NULL,
  `deskripsi` text,
  `harga_alat` int(11) DEFAULT '0' COMMENT 'Harga alat dalam rupiah',
  `tarif_denda_per_hari` int(11) DEFAULT '0' COMMENT 'Denda keterlambatan per hari',
  `foto` varchar(255) DEFAULT 'default-alat.png',
  `stok` int(11) NOT NULL DEFAULT '0',
  `stok_layak` int(11) DEFAULT '0' COMMENT 'Stok yang masih layak pakai',
  `kondisi` enum('baik','sedang','rusak') NOT NULL DEFAULT 'baik',
  `status` enum('tersedia','dipinjam','perawatan') NOT NULL DEFAULT 'tersedia',
  `tanggal_tambah` date DEFAULT NULL,
  `denda_2_hari` int(11) GENERATED ALWAYS AS ((coalesce(`tarif_denda_per_hari`,0) * 2)) STORED
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

