--
-- Table structure for table `denda`
--

CREATE TABLE `denda` (
  `id` int(11) NOT NULL,
  `peminjaman_id` int(11) NOT NULL,
  `jenis` enum('keterlambatan','kerusakan') NOT NULL,
  `hari_terlambat` int(11) DEFAULT '0',
  `tarif_per_hari` int(11) DEFAULT '0',
  `kondisi_kerusakan` enum('rusak_ringan','rusak_berat','hilang') DEFAULT NULL,
  `harga_alat_snapshot` int(11) DEFAULT '0' COMMENT 'Harga alat saat kejadian',
  `persentase` int(11) DEFAULT '0',
  `jumlah_unit` int(11) DEFAULT '1',
  `total_denda` int(11) NOT NULL DEFAULT '0',
  `status` enum('belum_bayar','lunas') DEFAULT 'belum_bayar',
  `catatan` text,
  `dibayar_at` timestamp NULL DEFAULT NULL,
  `dikonfirmasi_oleh` int(11) DEFAULT NULL COMMENT 'user id petugas yang konfirmasi',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

