-- --------------------------------------------------------

--
-- Table structure for table `peminjaman`
--

CREATE TABLE `peminjaman` (
  `id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `alat_id` int(11) NOT NULL,
  `jumlah` int(11) NOT NULL DEFAULT '1',
  `tanggal_pinjam` datetime DEFAULT NULL,
  `tanggal_pengembalian_rencana` datetime DEFAULT NULL,
  `tanggal_pengembalian_aktual` datetime DEFAULT NULL,
  `hari_terlambat` int(11) DEFAULT '0',
  `status_denda` enum('bebas','menunggu','lunas') DEFAULT 'bebas',
  `kondisi_pengembalian` enum('baik','rusak_ringan','rusak_berat','hilang') DEFAULT 'baik',
  `status_perbaikan` enum('perlu_perbaikan','sedang_diperbaiki','sudah_diperbaiki') DEFAULT NULL COMMENT 'Hanya diisi jika kondisi_pengembalian = rusak_ringan atau rusak_berat',
  `catatan_perbaikan` text,
  `tanggal_perbaikan` date DEFAULT NULL,
  `diperbaiki_oleh` int(11) DEFAULT NULL,
  `catatan_pengembalian` text,
  `denda` decimal(10,2) DEFAULT '0.00',
  `diperiksa_oleh` int(11) DEFAULT NULL,
  `status` enum('menunggu','disetujui','dipinjam','dikembalikan','ditolak','dibatalkan') NOT NULL DEFAULT 'menunggu',
  `catatan` text,
  `catatan_admin` text,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `ada_request_pengembalian` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 jika user sudah mengajukan request pengembalian yang belum selesai'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

