--
-- Table structure for table `pengembalian`
--

CREATE TABLE `pengembalian` (
  `id` int(11) NOT NULL,
  `peminjaman_id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `status` enum('menunggu','dikonfirmasi','selesai','dibatalkan') NOT NULL DEFAULT 'menunggu',
  `catatan_user` text,
  `dikonfirmasi_oleh` int(11) DEFAULT NULL,
  `tanggal_konfirmasi` datetime DEFAULT NULL,
  `catatan_konfirmasi` text,
  `diperiksa_oleh` int(11) DEFAULT NULL,
  `tanggal_pengecekan` datetime DEFAULT NULL,
  `kondisi_pengembalian` enum('baik','rusak_ringan','rusak_berat','hilang') DEFAULT NULL,
  `catatan_pengembalian` text,
  `tanggal_request` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

